<script setup lang="ts">import { nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'; import * as echarts from 'echarts'; import type { ProvinceDistribution, TypeDistribution } from '@/types/domain'; const props = defineProps<{ data: (ProvinceDistribution | TypeDistribution)[] }>(); const el = ref<HTMLElement>(); let chart: echarts.ECharts | undefined; function render() { if (!el.value) return; chart ??= echarts.init(el.value); chart.setOption({ tooltip: { trigger: 'item' }, legend: { bottom: 0, type: 'scroll', textStyle: { color: '#708895', fontSize: 11 } }, series: [{ type: 'pie', radius: ['48%', '70%'], center: ['50%', '42%'], label: { show: false }, data: props.data.map((item) => ({ name: 'provinceName' in item ? item.provinceName : item.enterpriseTypeName, value: item.count })) }], color: ['#118b82', '#ed775c', '#d9932f', '#4f84a7', '#91b9b2', '#d2a3a0'] }); } onMounted(() => nextTick(render)); watch(() => props.data, render, { deep: true }); onBeforeUnmount(() => chart?.dispose())</script>
<template><div ref="el" class="chart chart--donut"></div></template>
